LAYER
  NAME "c_denue_escuelas_primarias"
  STATUS ON
  TYPE POINT
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom FROM denue.escuelas_primarias) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Escuelas primarias (DENUE 2026)"
    "wms_enable_request" "*"
  END
  CLASS
    STYLE
      SYMBOL "circulor"
      SIZE 9
      OUTLINECOLOR 0 0 0
      COLOR 11 123 234
    END
  END
END

